import React, {Component, useState, useEffect} from "react";
import Config from "../scripts/config";
import axios from "axios";
// import { useNavigate } from "react-router-dom";
import DataTable from "react-data-table-component";

const History = props => {
    const [data, setData] = useState([]); // State lưu dữ liệu bảng
    const [lastFetchedData, setLastFetchedData] = useState(null); // Lưu dữ liệu lần fetch trước

    // Hàm kiểm tra dữ liệu có thay đổi không
    const isDataChanged = (newData, oldData) => {
        return JSON.stringify(newData) !== JSON.stringify(oldData);
    };

    // const data_table = [
    //     {
    //         id: 1,
    //         name: 'Document1',
    //         position: 'Locker 1',
    //         room: 'Room 1',
    //         email: 'phungquyduong051099@gmail.com',
    //         datetime: '111111'
    //     },
    //     {
    //         id: 2,
    //         name: 'Document2',
    //         position: 'Locker 2',
    //         room: 'Room2',
    //         email: 'kingstech2811@gmail.com',
    //         datetime: '22222'
    //     },

    // ]

    const [dataTable, setDataTable] = useState([]);
    const [newData, setNewData] = useState([]);

    const customStyles = {
        headCells: {
            style: {
                backgroundColor: "black",
                color: "white",
                fontSize: "17px",
                fontWeight: "bolder",
            }
        }
    }
    // Hàm GET dữ liệu
    const fetchData = async () => {
        try {
            const response = await axios.get("http://" + Config.ROSBRIDGE_SERVER_IP + ":" + Config.SERVER_PORT + "/history")
            setData(response.data.data);
            // length = response.data.data.length;
            setMessage(response.data.status);
            // console.log("dữ liệu phản hồi từ server cos chieu dai là:", length, pre_length);
            // if(pre_length !== length){
            //     pre_length = length;
            //     for (const newdata of response.data.data) {
            //         setDataTable([
            //             ...dataTable,
            //             {
            //                 name: newdata.doc_name,
            //                 position: newdata.locker_pos,
            //                 room: newdata.room_pos,
            //                 email: newdata.email,
            //                 datetime: newdata.create_time
            //             }
            //         ]);
            //     }

            //     setNewData(dataTable);
            //     console.log("-------------update data in table----------------", dataTable)
            //     setDataTable([]);
            // }
        } catch (error) {
            console.error("Error fetching data:", error);
        }
    };

    useEffect(() => {
        // setsendValue({...sendvalue, pwd: '', state: false});
        fetchData(); // Gọi lần đầu tiên khi component mount

        const interval = setInterval(() => {
          fetchData();
        //   console.log(dataTable);
        }, pollingInterval); // Lặp lại mỗi 5 giây

        return () => clearInterval(interval); // Xóa interval khi component unmount
    }, []);

    const columns = [
        {
            name: 'Name',
            selector: row => row.name,
            sortable: true
        },
        {
            name: 'Position',
            selector: row => row.position,
            sortable: true
        },
        {
            name: 'Room',
            selector: row => row.room,
            sortable: true
        },
        {
            name: 'Email',
            selector: row => row.email,
            sortable: true
        },
        {
            name: 'Date Created',
            selector: row => row.datetime,
            sortable: true
        }

    ];
    return(
        <div className="history-container mt5">
            <DataTable 
                columns={columns}
                data={newData}
                customStyles={customStyles}
                fixedHeader
                pagination
            ></DataTable>
        </div>
    );
}

export default History;
